#ifdef NDEBUG
#error "Assertions must remain enabled."
#endif
#include <cassert>
#include <iostream>
enum class Phase{Showing,Loading,Ready};
class Transition{
    int current_=0,target_=0,generation_=0;
    Phase phase_=Phase::Showing;
public:
    int begin(int target){
        if(target<0 || target>3)return -1;
        target_=target;phase_=Phase::Loading;return ++generation_;
    }
    bool complete(int token){
        if(token!=generation_ || phase_!=Phase::Loading)return false;
        phase_=Phase::Ready;return true;
    }
    bool commit(){
        if(phase_!=Phase::Ready)return false;
        current_=target_;phase_=Phase::Showing;return true;
    }
    void cancel(){++generation_;target_=current_;phase_=Phase::Showing;}
    int current()const{return current_;}
};
int main(){
    Transition t;int a=t.begin(1);assert(!t.commit());
    int b=t.begin(2);assert(!t.complete(a));assert(t.current()==0);
    assert(t.complete(b));assert(!t.complete(b));assert(t.commit());
    assert(t.current()==2 && !t.commit());
    int c=t.begin(3);t.cancel();assert(!t.complete(c));assert(t.current()==2);
    assert(t.begin(9)==-1 && t.current()==2);
    std::cout<<"transition token tests passed\n";
}
